create type party_type as enum ('artist','venue'); create type thread_kind as enum ('manager','booking'); create type sender_role as enum ('artist','venue','agent','system'); create type message_channel as enum ('text','voice'); create type availability_kind as enum ('date','weekly'); create type availability_source as enum ('chat','voice','manual'); create type suggestion_status as enum ('suggested','accepted','declined'); create type booking_status as enum ('negotiating','confirmed','paid_held','performed','released','refunded','cancelled'); create type payment_status as enum ('pending','held','released','refunded'); create type vetting_status as enum ('unverified','pending','verified','rejected');
alter table public.artists add column borough text,add column phone text,add column photo_path text,add column start_date date,add column set_length_min int,add column rate_usd int,add column goals text,add column intake_completed_at timestamptz,add column vetting vetting_status not null default 'unverified',add column vetting_note text;
alter table public.artists add constraint artists_user_unique unique(user_id);
alter table public.venues add column contact_name text,add column photo_path text,add column start_date date,add column set_length_min int,add column budget_usd int,add column capacity int,add column goals text,add column intake_completed_at timestamptz;
alter table public.venues add constraint venues_user_unique unique(user_id);
alter table public.venues alter column address set default '';
create table public.availability(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),owner_type party_type not null,owner_id uuid not null,kind availability_kind not null,date date,weekday int check(weekday between 0 and 6),start_time time not null default '19:00',end_time time not null default '23:00',note text,source availability_source not null default 'manual',check((kind='date' and date is not null) or (kind='weekly' and weekday is not null)));
grant all on public.availability to service_role; grant select,insert,update,delete on public.availability to authenticated;
create table public.threads(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),kind thread_kind not null,artist_id uuid references public.artists(id) on delete cascade,venue_id uuid references public.venues(id) on delete cascade,booking_id uuid,last_message_at timestamptz not null default now(),check(kind='booking' or num_nonnulls(artist_id,venue_id)=1));
grant all on public.threads to service_role; grant select on public.threads to authenticated;
create unique index one_manager_thread_per_artist on public.threads(artist_id) where kind='manager'; create unique index one_manager_thread_per_venue on public.threads(venue_id) where kind='manager';
create table public.messages(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),thread_id uuid not null references public.threads(id) on delete cascade,sender_role sender_role not null,sender_id uuid,channel message_channel not null default 'text',content text not null);
grant all on public.messages to service_role; grant select,insert on public.messages to authenticated;
create table public.mack_notes(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),owner_type party_type not null,owner_id uuid not null,thread_id uuid references public.threads(id) on delete set null,note text not null);
grant all on public.mack_notes to service_role; grant select on public.mack_notes to authenticated;
create table public.suggestions(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),venue_id uuid not null references public.venues(id) on delete cascade,artist_id uuid not null references public.artists(id) on delete cascade,score int not null default 0,reason text not null default '',slot_date date,slot_start time,status suggestion_status not null default 'suggested',unique(venue_id,artist_id));
grant all on public.suggestions to service_role; grant select on public.suggestions to authenticated;
alter table public.bookings add column suggestion_id uuid references public.suggestions(id) on delete set null,add column start_time time,add column set_length_min int,add column offer_usd int;
alter table public.bookings alter column offer_amount set default 0; alter table public.bookings alter column status set default 'negotiating';
update public.bookings set offer_usd=offer_amount,status=case status when 'pending' then 'negotiating' when 'declined' then 'cancelled' else status end;
comment on column public.bookings.offer_amount is 'DEPRECATED: replaced by offer_usd'; comment on column public.bookings.status is 'Shared booking_status values enforced by trigger; legacy text type retained for zero-downtime compatibility.'; comment on table public.swipes is 'DEPRECATED: replaced by suggestions'; comment on table public.booking_messages is 'DEPRECATED: replaced by messages and threads';
create function public.validate_booking_status() returns trigger language plpgsql set search_path=public as $$ begin perform new.status::public.booking_status; return new; end $$; create trigger validate_booking_status before insert or update on public.bookings for each row execute function public.validate_booking_status();
alter table public.threads add constraint threads_booking_fk foreign key(booking_id) references public.bookings(id) on delete cascade; create unique index one_thread_per_booking on public.threads(booking_id) where kind='booking';
create table public.payments(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),booking_id uuid not null unique references public.bookings(id) on delete cascade,amount_usd numeric(10,2) not null,fee_usd numeric(10,2) not null,payout_usd numeric(10,2) not null,whop_checkout_id text,whop_payment_id text,checkout_url text,status payment_status not null default 'pending');
grant all on public.payments to service_role; grant select on public.payments to authenticated;
create table public.expert_reviews(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),artist_id uuid not null references public.artists(id) on delete cascade,review_token text not null unique default replace(gen_random_uuid()::text,'-',''),terac_opportunity_id text,terac_submission_id text,verdict text check(verdict in ('verified','rejected')),room_fit text[],note text);
grant all on public.expert_reviews to service_role; grant select on public.expert_reviews to authenticated;
create table public.agent_log(id bigint generated always as identity primary key,at timestamptz not null default now(),agent text not null,action text not null,detail jsonb not null default '{}');
grant all on public.agent_log to service_role; grant usage,select on sequence public.agent_log_id_seq to service_role; grant select on public.agent_log to anon,authenticated;
create index on public.availability(owner_type,owner_id); create index on public.messages(thread_id,created_at); create index on public.suggestions(venue_id,status); create index on public.bookings(artist_id); create index on public.bookings(venue_id);
create or replace function public.touch_thread() returns trigger language plpgsql security definer set search_path=public as $$ begin update public.threads set last_message_at=new.created_at where id=new.thread_id; return new; end $$; create trigger messages_touch_thread after insert on public.messages for each row execute function public.touch_thread();
create or replace function public.owns_party(_type party_type,_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select case _type when 'artist' then exists(select 1 from artists where id=_id and user_id=auth.uid()) when 'venue' then exists(select 1 from venues where id=_id and user_id=auth.uid()) end $$;
create or replace function public.is_thread_party(_thread_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from threads t left join bookings b on b.id=t.booking_id where t.id=_thread_id and (owns_party('artist',coalesce(t.artist_id,b.artist_id)) or owns_party('venue',coalesce(t.venue_id,b.venue_id)))) $$;
do $$ declare p record; begin for p in select tablename,policyname from pg_policies where schemaname='public' and tablename in ('artists','venues','bookings') loop execute format('drop policy %I on public.%I',p.policyname,p.tablename); end loop; end $$;
grant all on public.artists,public.venues,public.bookings to service_role; revoke insert,update,delete on public.bookings from authenticated; grant select,insert,update on public.artists,public.venues to authenticated; grant select on public.bookings to authenticated;
alter table public.availability enable row level security; alter table public.threads enable row level security; alter table public.messages enable row level security; alter table public.mack_notes enable row level security; alter table public.suggestions enable row level security; alter table public.payments enable row level security; alter table public.expert_reviews enable row level security; alter table public.agent_log enable row level security;
create policy read on public.artists for select to authenticated using(true); create policy own_insert on public.artists for insert to authenticated with check(user_id=auth.uid()); create policy own_update on public.artists for update to authenticated using(user_id=auth.uid());
create policy read on public.venues for select to authenticated using(true); create policy own_insert on public.venues for insert to authenticated with check(user_id=auth.uid()); create policy own_update on public.venues for update to authenticated using(user_id=auth.uid());
create policy read on public.availability for select to authenticated using(true); create policy own_write on public.availability for all to authenticated using(owns_party(owner_type,owner_id)) with check(owns_party(owner_type,owner_id));
create policy party_read on public.threads for select to authenticated using(is_thread_party(id)); create policy party_read on public.messages for select to authenticated using(is_thread_party(thread_id)); create policy party_post on public.messages for insert to authenticated with check(sender_id=auth.uid() and sender_role in ('artist','venue') and is_thread_party(thread_id));
create policy own_read on public.mack_notes for select to authenticated using(owns_party(owner_type,owner_id)); create policy party_read on public.suggestions for select to authenticated using(owns_party('venue',venue_id) or owns_party('artist',artist_id)); create policy party_read on public.bookings for select to authenticated using(owns_party('venue',venue_id) or owns_party('artist',artist_id)); create policy party_read on public.payments for select to authenticated using(exists(select 1 from bookings b where b.id=booking_id and (owns_party('venue',b.venue_id) or owns_party('artist',b.artist_id)))); create policy read on public.expert_reviews for select to authenticated using(true); create policy read on public.agent_log for select to anon,authenticated using(true);
alter publication supabase_realtime add table public.messages,public.threads,public.availability,public.suggestions,public.payments,public.agent_log;
create policy media_read on storage.objects for select to authenticated using(bucket_id='media'); create policy media_own_write on storage.objects for insert to authenticated with check(bucket_id='media' and (storage.foldername(name))[1]=auth.uid()::text); create policy media_own_update on storage.objects for update to authenticated using(bucket_id='media' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='media' and (storage.foldername(name))[1]=auth.uid()::text);